import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import CandidateResumes from "./components/CandidateResumes";

/* ---------------- HOME PAGE ---------------- */

function Home() {
  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Job Portal Dashboard</h1>

      <div style={styles.cardContainer}>
        <Link to="/candidates/resumes" style={styles.card}>
          📄 Candidate Resumes
        </Link>
      </div>
    </div>
  );
}

/* ---------------- NAVBAR ---------------- */

function Navbar() {
  return (
    <div style={styles.navbar}>
      <Link to="/" style={styles.logo}>
        Job Portal
      </Link>

      <div style={styles.navLinks}>
        <Link to="/candidates/resumes" style={styles.link}>
          Resumes
        </Link>
      </div>
    </div>
  );
}

/* ---------------- MAIN APP ---------------- */

function App() {
  return (
    <Router>
      <Navbar />

      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/candidates/resumes" element={<CandidateResumes />} />
      </Routes>
    </Router>
  );
}

export default App;

/* ---------------- STYLES ---------------- */

const styles = {
  navbar: {
    display: "flex",
    justifyContent: "space-between",
    padding: "15px 40px",
    backgroundColor: "#6366f1",
    color: "white",
  },

  logo: {
    fontSize: "20px",
    fontWeight: "bold",
    textDecoration: "none",
    color: "white",
  },

  navLinks: {
    display: "flex",
    gap: "20px",
  },

  link: {
    color: "white",
    textDecoration: "none",
    fontWeight: "500",
  },

  container: {
    padding: "40px",
    fontFamily: "Segoe UI, sans-serif",
  },

  title: {
    color: "#6366f1",
  },

  cardContainer: {
    display: "flex",
    gap: "20px",
    marginTop: "30px",
  },

  card: {
    padding: "20px 30px",
    background: "#eef2ff",
    borderRadius: "10px",
    textDecoration: "none",
    color: "#4338ca",
    fontWeight: "600",
  },
};
